WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS prev_paid_at FROM payments), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessions_payments AS (SELECT id, order_id, amount, paid_at, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT order_id, DATE_TRUNC('YEAR', paid_at) AS year_start, MAX(paid_at) AS last_seen, ROUND(AVG(burst_id), 2) AS avg_burst_id, ROUND(AVG(burst_id), 2) AS avg_burst_id_2, COUNT(*) AS cnt, MAX(paid_at) AS last_seen_2, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_id FROM sessions_payments GROUP BY ROLLUP (order_id, DATE_TRUNC('YEAR', paid_at)) ORDER BY cnt DESC
